{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group rule lacks a description",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "The RDP ingress rule has no description, reducing the ability to identify its purpose during security reviews and incident response."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "RDP is exposed to the public internet",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "The rule permits TCP port 3389 from 0.0.0.0/0, exposing RDP to internet-wide scanning, brute-force attempts, and exploitation."
    }
  ],
  "patched_code": "resource \"aws_security_group_rule\" \"changeme_remote_exec_inline_security_group_rule_incoming_rdp\" {\n  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id\n  description       = \"Allow RDP access from private networks\"\n  type              = \"ingress\"\n  from_port         = 3389\n  to_port           = 3389\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"10.0.0.0/8\"]\n}\n",
  "fix_summary": "Added a descriptive label to the RDP rule and replaced unrestricted internet access with access limited to the private 10.0.0.0/8 address range."
}
